style.css:
@-moz-document domain("roblox.com") {
/* FORCE BACKGROUND */
    body, .content, .container-main, .gui-body, #wrap, .section-content {
        background: radial-gradient(circle at center, #0a2b0a 0%, #050505 100%) fixed !important;
        background-color: #050505 !important;
    }

    /* FORCE TEXT COLOR */
    * {
        color: white !important;
        font-family: "Impact", sans-serif !important;
    }

    /* FORCE HEADER GREEN */
    #header, .rbx-header, .header-2026 {
        background: #050505 !important;
        border-bottom: 3px solid #39ff14 !important;
    }

    /* FORCE CATALOG CARDS */
    .item-card, .item-card-container, .grid-item-container {
        background: rgba(0, 0, 0, 0.8) !important;
        border: 2px solid #39ff14 !important;
    }

    /* FORCE GREEN LINKS */
    a, .text-name, .text-title, .navbar-link {
        color: #39ff14 !important;
    }

    /* FORCE BUTTONS */
    .btn-primary-md, .buy-button, .login-button {
        background: #39ff14 !important;
        color: black !important;
        transform: skewX(-15deg) !important;
    }
}
